1	"use client";
2	
3	import { cn } from "@repo/design-system/lib/utils";
4	import { useEffect, useRef, useState } from "react";
5	import { StateCardShell } from "./card";
6	import { stepPaints, stepRender, stepReturns } from "./copy";
7	import { REPLAY_NOTES, REPLAY_WALK } from "./source";
8	
9	// The render tally lives outside the component on purpose: a value inside
10	// would be re-declared by the very renders it is meant to count. Written to
11	// the badge after paint, never rendered by JSX, so hydration has nothing to
12	// disagree with. (React's dev StrictMode double-invokes renders; the tally
13	// is honest in production.)
14	let renderTally = 0;
15	
16	// The replay's rhythm: flip out, then the walk — quick over plain lines,
17	// dwelling where an annotation lands — then flip back.
18	const FLIP_MS = 550;
19	const SWEEP_MS = 240;
20	const NOTE_MS = 1000;
21	const NOTE_LINES: ReadonlySet<number> = new Set(Object.values(REPLAY_NOTES));
22	
23	/** Which history slot a landing line lights, in reading order. */
24	const NOTE_INDEX: Readonly<Record<number, number>> = {
25	  [REPLAY_NOTES.fn]: 0,
26	  [REPLAY_NOTES.useState]: 1,
27	  [REPLAY_NOTES.paint]: 2,
28	};
29	
30	interface StateCardProps {
31	  /** Narrate mode: a press turns the card over and replays itself. */
32	  narrate: boolean;
33	  /** The card's back face — the source, Shiki-highlighted on the server. */
34	  replayCode: React.ReactNode;
35	}
36	
37	/**
38	 * The counter, with the replay on its back. A press updates state
39	 * immediately — the new number exists before the card finishes turning —
40	 * and in narrate mode the card flips to the source and replays the click
41	 * against it: the press (annotated with the closure's genuinely stale
42	 * read), the fresh call, the kept value coming back, the paint. Slowed,
43	 * not simulated; every value in the annotations was read live. Then it
44	 * turns back, and the number has moved.
45	 */
46	export function StateCard({ narrate, replayCode }: StateCardProps) {
47	  renderTally += 1;
48	  const renderNumber = renderTally;
49	
50	  const [count, setCount] = useState(0);
51	  const [flipped, setFlipped] = useState(false);
52	
53	  const badgeRef = useRef<HTMLSpanElement | null>(null);
54	  const codeRef = useRef<HTMLDivElement | null>(null);
55	  const notesRef = useRef<HTMLOListElement | null>(null);
56	  const numberRef = useRef<HTMLParagraphElement | null>(null);
57	  const digitsRef = useRef<HTMLSpanElement | null>(null);
58	  const timeoutsRef = useRef<ReturnType<typeof setTimeout>[]>([]);
59	  const replayingRef = useRef<boolean>(false);
60	
61	  // Ref guards compare against null, and the replay flag against true,
62	  // rather than testing truthiness: Biome's noUnnecessaryConditions reads
63	  // useRef's initializer as the whole type, so `if (ref.current)` is
64	  // reported as always falsy.
65	  useEffect(() => {
66	    if (badgeRef.current !== null) {
67	      badgeRef.current.textContent = `render #${renderNumber}`;
68	    }
69	  });
70	
71	  // Unmounting mid-replay: cancel the walk.
72	  useEffect(
73	    () => () => {
74	      for (const timeout of timeoutsRef.current) {
75	        clearTimeout(timeout);
76	      }
77	    },
78	    []
79	  );
80	
81	  const setActiveLine = (index: number | null) => {
82	    const lines = codeRef.current?.querySelectorAll(".line");
83	    if (!lines) {
84	      return;
85	    }
86	    lines.forEach((line, i) => {
87	      line.classList.toggle("ht-replay-active", i === index);
88	    });
89	  };
90	
91	  const schedule = (fn: () => void, ms: number) => {
92	    timeoutsRef.current.push(setTimeout(fn, ms));
93	  };
94	
95	  const noteItems = (): HTMLLIElement[] =>
96	    notesRef.current === null
97	      ? []
98	      : [...notesRef.current.querySelectorAll("li")];
99	
100	  const lightNote = (index: number | undefined) => {
101	    if (index === undefined) {
102	      return;
103	    }
104	    noteItems()[index]?.classList.add("ht-lit");
105	  };
106	
107	  const clearNotes = () => {
108	    for (const item of noteItems()) {
109	      item.textContent = "";
110	      item.classList.remove("ht-lit");
111	    }
112	  };
113	
114	  const handleClick = () => {
115	    if (replayingRef.current === true) {
116	      return;
117	    }
118	    const next = count + 1;
119	    setCount(next);
120	
121	    if (!narrate) {
122	      return;
123	    }
124	
125	    replayingRef.current = true;
126	    timeoutsRef.current = [];
127	    setFlipped(true);
128	    // The whole record is on the card before the walk begins — all three
129	    // annotations, dimmed — so a reader can take them in at their own pace.
130	    // Values are read at fire time; the render this history names has
131	    // happened by mid-flip.
132	    schedule(
133	      () => {
134	        const texts = [
135	          stepRender(renderTally),
136	          stepReturns(next),
137	          stepPaints(next),
138	        ];
139	        noteItems().forEach((item, index) => {
140	          item.textContent = texts[index] ?? "";
141	          item.classList.remove("ht-lit");
142	        });
143	      },
144	      Math.round(FLIP_MS / 2)
145	    );
146	    // The walk re-runs the component the way a render does: top to bottom,
147	    // every line with code on it — dwelling where a history line lights up,
148	    // and each stays lit once lit.
149	    let at = FLIP_MS;
150	    for (const line of REPLAY_WALK) {
151	      schedule(() => {
152	        setActiveLine(line);
153	        lightNote(NOTE_INDEX[line]);
154	      }, at);
155	      at += NOTE_LINES.has(line) ? NOTE_MS : SWEEP_MS;
156	    }
157	    schedule(() => {
158	      setFlipped(false);
159	      setActiveLine(null);
160	      clearNotes();
161	      // The paint happened while the card was turned; the wash marks its
162	      // reveal (re-triggered by hand — a keyed remount already played it
163	      // behind the card's back). The class comes off, the layout read
164	      // flushes that removal, and the class goes back on: without the read
165	      // in the middle the browser coalesces both mutations into one frame
166	      // and the animation never restarts. getAnimations() is no help here —
167	      // a finished fill:none animation is gone from it by the time we ask.
