() => { const px = (fills) => { const c = document.createElement('canvas'); c.width=c.height=1; const x=c.getContext('2d'); for (const f of fills) { x.fillStyle=f; x.fillRect(0,0,1,1); } const d=x.getImageData(0,0,1,1).data; return [d[0],d[1],d[2]]; };
 const lum = ([r,g,b]) => { const f=c=>{c/=255; return c<=0.03928?c/12.92:((c+0.055)/1.055)**2.4;}; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
 const ratio=(a,b)=>{const l1=lum(a),l2=lum(b);return Math.round(((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05))*100)/100;};
 const run = (dark) => { document.documentElement.classList.toggle('dark', dark); const bodyBg = getComputedStyle(document.body).backgroundColor; const bg = px([bodyBg]); const out = { bodyBg };
   const eyebrow = document.querySelector('.ht-reveal .font-mono span'); const dt = document.querySelector('dl dt');
   for (const [label, el] of [['eyebrow name', eyebrow], ['panel dt', dt]]) { if (!el) { out[label] = 'not found'; continue; } const cs = getComputedStyle(el); out[label] = { color: cs.color, size: cs.fontSize, ratio: ratio(px([bodyBg, cs.color]), bg) }; }
   return out; };
 const light = run(false); const dark = run(true); document.documentElement.classList.remove('dark'); return { light, dark }; }

