() => { const px=(f)=>{const c=document.createElement('canvas');c.width=c.height=1;const x=c.getContext('2d');for(const s of f){x.fillStyle=s;x.fillRect(0,0,1,1);}const d=x.getImageData(0,0,1,1).data;return [d[0],d[1],d[2]];};
 const lum=([r,g,b])=>{const f=c=>{c/=255;return c<=0.03928?c/12.92:((c+0.055)/1.055)**2.4;};return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b);};
 const ratio=(a,b)=>{const l1=lum(a),l2=lum(b);return Math.round(((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05))*100)/100;};
 const host=document.createElement('div'); document.body.appendChild(host);
 const run=(dark)=>{ document.documentElement.classList.toggle('dark',dark); const bodyBg=getComputedStyle(document.body).backgroundColor; const bg=px([bodyBg]); const out={};
  const classes = dark ? ['text-ht-cyan-300','text-ht-cyan-200','text-muted-foreground/70','text-muted-foreground/80','text-muted-foreground'] : ['text-ht-cyan-700','text-ht-cyan-800','text-ht-cyan-900','text-muted-foreground/70','text-muted-foreground/80','text-muted-foreground'];
  for(const cls of classes){const s=document.createElement('span');s.className=cls;host.appendChild(s);out[cls]=ratio(px([bodyBg,getComputedStyle(s).color]),bg);}
  host.innerHTML=''; return out; };
 const light=run(false); const dark=run(true); document.documentElement.classList.remove('dark'); host.remove(); return {light,dark}; }

